    gross_pct: (() => { const jp = projects.filter(p => p.completed >= start && p.completed <= end && (dept === 'all' || p.dept === dept)); const ww = ((K.wip && K.wip.rows) || []).filter(w => w.as_of >= start && w.as_of <= end && (dept === 'all' || w.dept === dept)); let rv = 0, cs = 0; jp.forEach(p => { rv += Number(p.gross); cs += Math.round(Number(p.materials) / 1.05 * 100) / 100 + Math.round(Number(p.other_cost) / 1.05 * 100) / 100 + Number(p.labour); }); ww.forEach(w => { rv += Number(w.billed_to_date); cs += Number(w.cost_to_date); }); return rv ? (rv - cs) / rv : null; })(),
    books_gross_pct: f.income ? (f.gross_adj != null ? f.gross_adj : f.gross) / f.income : null,
    net_pct: (() => { const nf = x => x == null || x.net == null && x.net_adj == null ? null : Number(x.net_adj != null ? x.net_adj : x.net); if (!f.income) return null; if (dept === 'all') return nf(f) / f.income; const adm = financials.find(x => x.period === period && x.dept === 'administration'), ns = financials.find(x => x.period === period && x.dept === 'not_specified'); const zero = financials.filter(x => x.period === period && ['installation', 'service', 'maintenance'].includes(x.dept) && !x.income).reduce((s, x) => s + (nf(x) || 0), 0); const pool = (nf(adm) || 0) + (nf(ns) || 0) + zero; return (nf(f) + pool * f.income / all.income) / f.income; })(),
