  const rv = logged.reduce((s, j) => s + j.c.revenue, 0), gp = logged.reduce((s, j) => s + j.c.gp, 0), avg = rv ? gp / rv : null;
  const sorted = logged.filter(j => j.c.margin != null).sort((a, b) => b.c.margin - a.c.margin), best = sorted[0], worst = sorted[sorted.length - 1];
