  parts.push(acc('jobs', 'Jobs behind the average ticket', jr.length + ' jobs', tbl(['Completed', 'Job', 'Customer', 'Revenue', 'Rebate claim', 'Lead source'], jr.map(p => tr([esc(dshort(p.completed)), esc(p.job), esc(p.customer), money(Number(p.gross)), Number(p.rebate_claim) ? money(Number(p.rebate_claim)) : '', esc(p.lead_source || '')], [3, 4])), [3, 4])));
  const er = E.filter(e => e.created >= start && e.created <= end && inDept(e)).sort((a, b) => a.created < b.created ? 1 : -1);
  const stc = { won: 'var(--green)', pending: 'var(--accent)', lost: 'var(--red)' };
  parts.push(acc('est', 'Estimates behind the close ratio', er.length + ' estimates · ' + er.filter(e => e.result === 'won').length + ' won', tbl(['Estimate', 'Created', 'Customer', 'Value', 'Result'], er.map(e => { const k = e.result === 'won' ? 'won' : e.result === 'pending' ? 'pending' : 'lost'; return tr([esc(e.estimate), esc(dshort(e.created)), esc(e.customer), money(Number(e.value)), `<span class="st" style="--c:${stc[k]}">${esc(e.result)}</span>`], [3]); }), [3])));
  const m = {}; jr.forEach(p => { const k = p.lead_source || 'Unknown'; m[k] = m[k] || { jobs: 0, gross: 0 }; m[k].jobs++; m[k].gross += Number(p.gross); });
